const request = $json.body && typeof $json.body === 'object' ? $json.body : ($json || {});
const requestedAction = String(request.action || 'preflight').trim();
const action = requestedAction === 'storePreflight' ? 'preflight' : requestedAction;
if (!['preflight','videoUploadProbe'].includes(action)) throw new Error('不支持的 OZON 预检操作: ' + requestedAction);
if (action === 'videoUploadProbe') return [{ json: {
  action,
  isVideoProbe: true,
  triggerSource: 'WEBHOOK',
  sourceFilePath: String(request.sourceFilePath || '').trim(),
  offerId: String(request.offerId || request.offer_id || '').trim()
} }];
const storeId = String(request.storeId || '').trim();
const storeConfigVersion = Number(request.storeConfigVersion || 0);
const credentialVersionId = String(request.credentialVersionId || '').trim();
const rowVersion = Number(request.rowVersion || 0);
if (!/^[0-9a-f-]{36}$/i.test(storeId)) throw new Error('storeId 必须是 UUID');
if (!Number.isInteger(storeConfigVersion) || storeConfigVersion < 1) throw new Error('storeConfigVersion 必须是正整数');
if (!/^[0-9a-f-]{36}$/i.test(credentialVersionId)) throw new Error('credentialVersionId 必须是 UUID');
if (!Number.isInteger(rowVersion) || rowVersion < 1) throw new Error('rowVersion 必须是正整数');
return [{ json: {
  action,
  isVideoProbe: false,
  triggerSource: 'WEBHOOK',
  storeId,
  storeConfigVersion,
  credentialVersionId,
  rowVersion,
  claimRequestRef: String(request.requestRef || '').trim(),
  offerId: String(request.offerId || request.offer_id || '').trim()
} }];

const crypto = require('crypto');
const requests = [
  ['sellerInfo', {}],
  ['limits', {}],
  ['warehouses', {}]
];
return $input.all().flatMap((item) => {
  const input = item.json || {};
  const source = String(input.triggerSource || 'WEBHOOK').toUpperCase();
  if (!['WEBHOOK','SCHEDULE'].includes(source)) throw new Error('OZON 预检 triggerSource 无效');
  const scopedRequests = [...requests];
  if (input.offerId) scopedRequests.push(
    ['infoList', { offer_id: [input.offerId] }],
    ['attributesInfo', { filter: { offer_id: [input.offerId] }, limit: 100 }],
    ['pricesRead', { cursor: '', filter: { offer_id: [input.offerId], visibility: 'ALL' }, limit: 100 }],
    ['stocksRead', { cursor: '', filter: { offer_id: [input.offerId], visibility: 'ALL' }, limit: 100 }]
  );
  const executionId = typeof $execution === 'object' && $execution ? String($execution.id || '') : '';
  const runSeed = String(input.claimRequestRef || executionId || (input.storeId + ':' + Date.now() + ':' + Math.random()));
  const runHash = crypto.createHash('sha256').update(runSeed).digest('hex').slice(0, 24);
  const base = source + ':' + input.storeId + ':cfg:' + input.storeConfigVersion + ':cred:' + input.credentialVersionId + ':run:' + runHash;
  return scopedRequests.map(([operation, payload]) => ({ json: {
    storeId: input.storeId,
    requestRef: 'preflight:' + base + ':' + operation,
    operation,
    payload
  } }));
});

const prepared = $('准备只读检查').all().map((item) => item.json || {});
const responses = $input.all().map((item) => item.json || {});
const requestPattern = /^preflight:(WEBHOOK|SCHEDULE):([0-9a-f-]{36}):cfg:(\d+):cred:([0-9a-f-]{36}):run:([a-f0-9]{24}):([A-Za-z][A-Za-z0-9]*)$/i;
const groups = new Map();
for (const request of prepared) {
  const match = String(request.requestRef || '').match(requestPattern);
  if (!match || String(request.storeId || '') !== match[2] || String(request.operation || '') !== match[6]) {
    throw new Error('OZON 预检准备请求关联字段无效');
  }
  const key = match[2] + ':' + match[3] + ':' + match[4];
  if (!groups.has(key)) groups.set(key, {
    triggerSource: match[1].toUpperCase(),
    storeId: match[2],
    storeConfigVersion: Number(match[3]),
    credentialVersionId: match[4],
    preparedByOperation: new Map(),
    responseByOperation: new Map()
  });
  const group = groups.get(key);
  if (group.preparedByOperation.has(match[6])) throw new Error('OZON 预检准备了重复 operation');
  group.preparedByOperation.set(match[6], request);
}
for (const [responseIndex, response] of responses.entries()) {
  const inputIndex = Number.isInteger(Number(response.inputIndex)) ? Number(response.inputIndex) : responseIndex;
  const request = prepared[inputIndex];
  if (!request) throw new Error('OZON 预检响应 inputIndex 越界');
  const match = String(request.requestRef || '').match(requestPattern);
  const key = match[2] + ':' + match[3] + ':' + match[4];
  const group = groups.get(key);
  const operation = match[6];
  if (String(response.operation || '') && String(response.operation) !== operation) throw new Error('OZON 预检响应 operation 不匹配');
  if (group.responseByOperation.has(operation)) throw new Error('OZON 预检收到重复 operation 响应');
  group.responseByOperation.set(operation, response);
}
return [...groups.values()].map((group) => {
  const byOperation = Object.fromEntries(group.responseByOperation);
  const responseResult = (operation) => byOperation[operation]?.result || byOperation[operation]?.body || {};
  const sellerRaw = responseResult('sellerInfo');
  const seller = sellerRaw.result && typeof sellerRaw.result === 'object' ? sellerRaw.result : sellerRaw;
  const company = seller.company && typeof seller.company === 'object' ? seller.company : {};
  const limits = responseResult('limits');
  const warehousesRaw = responseResult('warehouses');
  const warehouseRows = Array.isArray(warehousesRaw)
    ? warehousesRaw
    : Array.isArray(warehousesRaw.result)
      ? warehousesRaw.result
      : Array.isArray(warehousesRaw.warehouses)
        ? warehousesRaw.warehouses
        : Array.isArray(warehousesRaw.items) ? warehousesRaw.items : [];
  const warehouses = warehouseRows.map((entry) => {
    const type = String(entry.type || '').trim().toUpperCase();
    const fulfillmentModes = [...new Set([
      ...(Array.isArray(entry.fulfillment_modes) ? entry.fulfillment_modes : []),
      ...(entry.is_rfbs || type === 'RFBS' || type.includes('RFBS') ? ['RFBS'] : []),
      ...(entry.is_fbs || (!type.includes('RFBS') && (type === 'FBS' || type.includes('FBS'))) ? ['FBS'] : [])
    ].map((value) => String(value).trim().toUpperCase()).filter((value) => ['FBS','RFBS'].includes(value)))];
    return {
      id: String(entry.warehouse_id || entry.id || ''),
      name: String(entry.name || entry.warehouse_name || ''),
      fulfillmentModes,
      ...(entry.status ? { status: String(entry.status) } : {})
    };
  }).filter((entry) => entry.id && entry.fulfillmentModes.length > 0);
  const currency = String(seller.currency || company.currency || '').trim().toUpperCase();
  const requiredOperations = ['sellerInfo','limits','warehouses'];
  const rateLimited = (operation) => Number(byOperation[operation]?.statusCode || 0) === 429
    || String(byOperation[operation]?.error?.code || '').toUpperCase() === 'TOO_MANY_REQUESTS';
  const operationPassed = (operation) => byOperation[operation]?.ok === true && (operation !== 'warehouses' || warehouses.length > 0);
  const failed = requiredOperations.filter((operation) => !operationPassed(operation));
  const checks = requiredOperations.map((operation) => {
    const passed = operationPassed(operation);
    return {
      code: operation === 'sellerInfo' ? 'SELLER_IDENTITY' : operation === 'limits' ? 'PRODUCT_LIMITS' : 'WAREHOUSES',
      ok: passed,
      status: rateLimited(operation) ? 'RATE_LIMITED' : passed ? 'PASSED' : 'FAILED',
      ...(byOperation[operation]?.error?.message ? { message: String(byOperation[operation].error.message).slice(0, 500) } : {}),
      details: operation === 'limits' ? { operationLimits: limits.operation_limits || limits.operationLimits || [] } : {}
    };
  });
  const sellerPassed = operationPassed('sellerInfo');
  const currencyStatus = currency ? 'VERIFIED' : sellerPassed ? 'DEFERRED_EMPTY_CATALOG' : 'FAILED';
  checks.push({
    code: 'CURRENCY_EVIDENCE',
    ok: currencyStatus !== 'FAILED',
    status: currencyStatus === 'VERIFIED' ? 'PASSED' : currencyStatus === 'DEFERRED_EMPTY_CATALOG' ? 'DEFERRED' : rateLimited('sellerInfo') ? 'RATE_LIMITED' : 'FAILED',
    message: currencyStatus === 'VERIFIED' ? '币种证据已验证' : currencyStatus === 'DEFERRED_EMPTY_CATALOG'
      ? '空店暂无可验证币种的商品价格证据' : '币种证据验证失败'
  });
  const ok = failed.length === 0 && warehouses.length > 0 && currencyStatus !== 'FAILED';
  const hasRateLimit = requiredOperations.some(rateLimited);
  return { json: {
    triggerSource: group.triggerSource,
    storeId: group.storeId,
    storeConfigVersion: group.storeConfigVersion,
    credentialVersionId: group.credentialVersionId,
    sellerId: String(seller.seller_id || seller.id || company.inn || ''),
    sellerName: String(seller.company_name || seller.name || company.name || company.legal_name || ''),
    checks,
    warehouses,
    permissions: Array.isArray(seller.permissions) ? seller.permissions.map(String) : [],
    limits,
    currencyVerified: currencyStatus === 'VERIFIED',
    currencyVerification: {
      status: currencyStatus,
      ...(currency ? { currency } : {}),
      source: currency ? 'SELLER_INFO' : 'EMPTY_CATALOG',
      evidence: currency ? { sellerCurrency: currency } : { productCount: 0 }
    },
    retryAfterMs: Math.max(0, ...Object.values(byOperation).map((entry) => Number(entry.retryAfterMs || 0))),
    observedAt: new Date().toISOString(),
    ok,
    ...(ok ? {} : { errorCode: hasRateLimit ? 'OZON_PREFLIGHT_RATE_LIMITED' : failed.length ? 'OZON_PREFLIGHT_API_FAILED' : 'OZON_WAREHOUSE_REQUIRED', errorMessage: hasRateLimit ? 'OZON 预检触发限流' : failed.length ? '店铺只读预检失败' : '店铺没有可用仓库' })
  } };
});

const fs = require('fs');
const path = require('path');
const request = $('解析预检动作').first().json || {};
const sourceFilePath = String(request.sourceFilePath || '').trim();
if (!sourceFilePath || !path.isAbsolute(sourceFilePath)) throw new Error('视频探测必须提供本地 MP4 绝对路径');
const resolved = fs.realpathSync(sourceFilePath);
const stat = fs.statSync(resolved);
if (!stat.isFile() || path.extname(resolved).toLowerCase() !== '.mp4') throw new Error('视频探测文件必须是普通 .mp4 文件');
if (stat.size < 12 || stat.size > 1024 * 1024 * 1024) throw new Error('视频探测文件大小不在 12B 到 1GB 范围内');
const data = fs.readFileSync(resolved);
if (data.subarray(4, 8).toString('ascii') !== 'ftyp') throw new Error('视频探测文件不是有效 MP4（缺少 ftyp 标识）');
const sourceFileName = path.basename(resolved);
return [{
  json: { input: { sourceFileName, inputIndex: 0 } },
  binary: { data: { data: data.toString('base64'), fileName: sourceFileName, mimeType: 'video/mp4', fileSize: stat.size } }
}];

const upload = $('调用 OZON-S002 探测视频').first().json || {};
const response = $input.first();
const statusCode = Number(response.json?.statusCode || 200);
const headers = response.json?.headers || {};
const contentType = String(headers['content-type'] || headers['Content-Type'] || response.binary?.data?.mimeType || upload.mimeType || '').toLowerCase();
const ready = statusCode >= 200 && statusCode < 400 && contentType.startsWith('video/');
return [{ json: {
  ready,
  ok: ready,
  httpStatus: ready ? 200 : 503,
  publicStatus: statusCode,
  contentType,
  message: ready ? 'SiliconFlow MP4 上传与公网读取验证通过' : 'SiliconFlow MP4 公网 URL 不可读取或 MIME 不是 video/*'
} }];

const raw = $input.first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const stores = body.stores;
if (!Array.isArray(stores)) throw new Error('OZON 预检 claim 响应必须包含 stores 数组');
if (stores.length > 20) throw new Error('OZON 预检 claim 超过每小时安全上限 20');
const seen = new Set();
return stores.map((store, index) => {
  const allowedKeys = new Set(['storeId','storeAlias','storeConfigVersion','credentialVersionId','requestRef','lockExpiresAt']);
  if (!store || typeof store !== 'object' || Array.isArray(store) || Object.keys(store).some((key) => !allowedKeys.has(key))) {
    throw new Error('OZON 预检 claim 第 ' + (index + 1) + ' 项不符合 strict 响应合同');
  }
  const storeId = String(store?.storeId || '').trim();
  const storeAlias = String(store?.storeAlias || '').trim().toLowerCase();
  const storeConfigVersion = Number(store?.storeConfigVersion || 0);
  const credentialVersionId = String(store?.credentialVersionId || '').trim();
  const claimRequestRef = String(store?.requestRef || '').trim();
  const lockExpiresAt = String(store?.lockExpiresAt || '').trim();
  if (!/^[0-9a-f-]{36}$/i.test(storeId)
    || !/^[a-z0-9][a-z0-9-]{1,31}$/.test(storeAlias)
    || !Number.isInteger(storeConfigVersion) || storeConfigVersion < 1
    || !/^[0-9a-f-]{36}$/i.test(credentialVersionId)
    || !/^[A-Za-z0-9._:|-]{1,240}$/.test(claimRequestRef)
    || !Number.isFinite(Date.parse(lockExpiresAt)) || Date.parse(lockExpiresAt) <= Date.now()) {
    throw new Error('OZON 预检 claim 第 ' + (index + 1) + ' 项缺少 store/config/credential 冻结快照');
  }
  const key = storeId + ':' + storeConfigVersion + ':' + credentialVersionId;
  if (seen.has(key)) throw new Error('OZON 预检 claim 返回重复店铺快照');
  seen.add(key);
  return { json: {
    action: 'preflight',
    isVideoProbe: false,
    triggerSource: 'SCHEDULE',
    storeId,
    storeAlias,
    storeConfigVersion,
    credentialVersionId,
    rowVersion: 0,
    claimRequestRef,
    lockExpiresAt,
    offerId: ''
  } };
});

async function ozonRuntimeRequest(method, endpoint, body, timeoutMs = 60_000) {
  const base = String($env.MERCHROUTE_RUNTIME_BASE_URL || 'http://127.0.0.1:4173').replace(/\/+$/, '');
  const key = String($env.MERCHROUTE_RUNTIME_KEY || '').trim();
  if (!key) {
    const error = new Error('MERCHROUTE_RUNTIME_KEY 未配置，无法访问 MerchRoute OZON runtime API');
    error.code = 'RUNTIME_KEY_MISSING';
    error.beforeSend = true;
    throw error;
  }
  const RuntimeURL = require('url').URL;
  const target = new RuntimeURL(base + endpoint);
  if (!['http:', 'https:'].includes(target.protocol)) throw new Error('MerchRoute runtime URL 协议无效');
  const payload = body === undefined ? '' : JSON.stringify(body);
  const transport = target.protocol === 'https:' ? require('https') : require('http');
  const response = await new Promise((resolve, reject) => {
    const request = transport.request(target, {
      method,
      headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json',
        'X-MerchRoute-Runtime-Key': key,
        ...(payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}),
      },
    }, (incoming) => {
      const chunks = [];
      let bytes = 0;
      incoming.on('data', (chunk) => {
        bytes += chunk.length;
        if (bytes > 20 * 1024 * 1024) {
          request.destroy(new Error('MerchRoute runtime API 响应超过 20 MiB 限制'));
          return;
        }
        chunks.push(chunk);
      });
      incoming.on('end', () => resolve({
        status: Number(incoming.statusCode || 0),
        text: Buffer.concat(chunks).toString('utf8'),
      }));
    });
    request.setTimeout(Math.max(1_000, Math.min(180_000, Number(timeoutMs) || 60_000)), () => {
      const error = new Error('MerchRoute runtime API 请求超时');
      error.code = 'RUNTIME_REQUEST_TIMEOUT';
      request.destroy(error);
    });
    request.on('error', reject);
    if (payload) request.write(payload);
    request.end();
  });
  let data = {};
  if (response.text) {
    try { data = JSON.parse(response.text); }
    catch (_) { data = { raw: response.text.slice(0, 2_000) }; }
  }
  if (response.status < 200 || response.status >= 300) {
    const nested = data && typeof data.error === 'object' && data.error !== null ? data.error : {};
    const error = new Error(String(data.message || nested.message || data.error || data.code || nested.code || ('MerchRoute runtime API HTTP ' + response.status)));
    error.code = String(data.code || nested.code || 'RUNTIME_API_FAILED');
    error.httpStatus = response.status;
    error.details = data;
    throw error;
  }
  return data;
}

return (async () => {
  const outputs = [];
  for (const item of $input.all()) {
    const source = item.json || {};
    const triggerSource = String(source.triggerSource || 'WEBHOOK').toUpperCase();
    const { triggerSource: _internalSource, ...report } = source;
    const storeId = String(report.storeId || '');
    const storeConfigVersion = Number(report.storeConfigVersion || 0);
    const credentialVersionId = String(report.credentialVersionId || '');
    const saved = await ozonRuntimeRequest('POST', '/api/v1/ozon/runtime/stores/' + encodeURIComponent(storeId) + '/preflight-result', {
      storeConfigVersion,
      credentialVersionId,
      report
    });
    outputs.push({ json: {
      ...report,
      triggerSource,
      persisted: true,
      reportVersion: Number(saved.reportVersion || saved.version || 1),
      ttlHours: 24,
      refreshDueHours: 18,
      httpStatus: report.ok ? 200 : 503
    } });
  }
  return outputs;
})();
